-- ============================================
-- LUMA — Thème 10 : LONG 3/3 x4 — Un procès final où l'utilisateur plaide sa déduction
-- ============================================


update scenarios set content = '{"characters": {"judge": "le juge", "defense": "l''avocat de la défense", "partner": "votre collègue"}, "start_node": "n1", "nodes": {"n1": {"speaker": "judge", "text": "The court is ready to hear the prosecution''s case. Detective, please present your findings.", "text_fr": "La cour est prête à entendre le dossier de l''accusation. Détective, veuillez présenter vos conclusions.", "choices": [{"text": "Your honor, the evidence conclusively points to the defendant''s involvement.", "text_fr": "Votre honneur, les preuves pointent de manière concluante vers l''implication de l''accusé.", "next": "n2"}, {"text": "I''ll walk the court through the timeline of evidence we uncovered.", "text_fr": "Je vais présenter à la cour la chronologie des preuves qu''on a découvertes.", "next": "n2"}]}, "n2": {"speaker": "judge", "text": "Proceed, detective. The court is listening carefully.", "text_fr": "Continuez, détective. La cour écoute attentivement.", "choices": [{"text": "First, the fingerprints found at the scene match the defendant''s, confirmed by two independent labs.", "text_fr": "D''abord, les empreintes trouvées sur la scène correspondent à celles de l''accusé, confirmées par deux laboratoires indépendants.", "next": "n3"}]}, "n3": {"speaker": "defense", "text": "Objection, your honor! Fingerprints alone don''t prove intent or presence at the time of the crime.", "text_fr": "Objection, votre honneur ! Les empreintes seules ne prouvent pas l''intention ou la présence au moment du crime.", "choices": [{"text": "I understand, your honor. Allow me to present the corroborating timeline as well.", "text_fr": "Je comprends, votre honneur. Permettez-moi de présenter aussi la chronologie corroborante.", "next": "n4"}]}, "n4": {"speaker": "judge", "text": "Objection noted, but overruled for now. Continue, detective.", "text_fr": "Objection notée, mais rejetée pour l''instant. Continuez, détective.", "choices": [{"text": "The security footage places the defendant''s vehicle near the scene at the exact time of the crime.", "text_fr": "Les images de sécurité placent le véhicule de l''accusé près de la scène au moment exact du crime.", "next": "n5"}]}, "n5": {"speaker": "defense", "text": "That footage is grainy at best! It could be any similar vehicle in the area.", "text_fr": "Ces images sont floues au mieux ! Ça pourrait être n''importe quel véhicule similaire dans le coin.", "choices": [{"text": "The license plate, though partially obscured, matches three of the defendant''s plate numbers.", "text_fr": "La plaque d''immatriculation, bien que partiellement obscurcie, correspond à trois des chiffres de la plaque de l''accusé.", "next": "n6"}, {"text": "Combined with the fingerprint evidence, this isn''t coincidental, your honor.", "text_fr": "Combiné avec les preuves d''empreintes, ce n''est pas une coïncidence, votre honneur.", "next": "n6"}]}, "n6": {"speaker": "judge", "text": "A compelling combination of evidence. Defense, your response?", "text_fr": "Une combinaison de preuves convaincante. Défense, votre réponse ?", "choices": [{"text": "(Wait for the defense''s rebuttal, prepared to counter it.)", "text_fr": "(Attends la réfutation de la défense, prêt à la contrer.)", "next": "n7"}]}, "n7": {"speaker": "defense", "text": "My client has an alibi — he was with a business associate that entire evening!", "text_fr": "Mon client a un alibi — il était avec un associé d''affaires toute la soirée !", "choices": [{"text": "That associate''s testimony contradicts itself on three separate occasions, your honor.", "text_fr": "Le témoignage de cet associé se contredit à trois occasions distinctes, votre honneur.", "next": "n8"}]}, "n8": {"speaker": "judge", "text": "Contradicts itself how, detective? Please elaborate for the court.", "text_fr": "Se contredit comment, détective ? Veuillez élaborer pour la cour.", "choices": [{"text": "The associate first claimed they were at a restaurant, then later said a private residence, with no explanation for the discrepancy.", "text_fr": "L''associé a d''abord affirmé être dans un restaurant, puis plus tard dans une résidence privée, sans explication pour la différence.", "next": "n9"}]}, "n9": {"speaker": "defense", "text": "(Flustered) That''s merely a memory lapse, easily explained by the stress of questioning!", "text_fr": "(Déstabilisé) C''est simplement un trou de mémoire, facilement expliqué par le stress de l''interrogatoire !", "choices": [{"text": "Perhaps, but combined with the physical evidence, the pattern points clearly to guilt.", "text_fr": "Peut-être, mais combiné avec les preuves physiques, le schéma pointe clairement vers la culpabilité.", "next": "n10"}]}, "n10": {"speaker": "judge", "text": "The court will take a brief recess to consider all evidence presented today.", "text_fr": "La cour va prendre une brève suspension pour considérer toutes les preuves présentées aujourd''hui.", "choices": [{"text": "(Wait anxiously during the recess, reviewing your case in your mind.)", "text_fr": "(Attends anxieusement pendant la suspension, en révisant ton dossier dans ta tête.)", "next": "n11"}]}, "n11": {"speaker": "judge", "text": "(Returns) After careful consideration, the court finds the prosecution''s evidence compelling and consistent.", "text_fr": "(Revient) Après considération attentive, la cour trouve les preuves de l''accusation convaincantes et cohérentes.", "choices": [{"text": "(Await the final verdict, having presented the strongest case possible.)", "text_fr": "(Attends le verdict final, ayant présenté le dossier le plus solide possible.)", "next": "n12"}]}, "n12": {"speaker": "judge", "text": "The defendant is found guilty on all counts. This court thanks the detective for thorough, meticulous work.", "text_fr": "L''accusé est déclaré coupable sur tous les chefs d''accusation. Cette cour remercie le détective pour un travail minutieux et méticuleux.", "choices": [{"text": "Thank you, your honor. Justice has been served through careful investigation.", "text_fr": "Merci, votre honneur. La justice a été rendue grâce à une enquête minutieuse.", "next": "end_won"}]}, "end_won": {"speaker": "partner", "text": "Congratulations, detective. Your deduction and presentation just closed one of our toughest cases.", "text_fr": "Félicitations, détective. Votre déduction et présentation viennent de clore l''une de nos affaires les plus difficiles.", "end": true, "ending_label": "Procès gagné grâce à une argumentation solide ⚖️🏆"}}}'::jsonb, is_playable = true
where title = 'Un procès final où l''''utilisateur plaide sa déduction'
  and theme_id = (select id from scenario_themes where position = 10 and language_id = (select id from languages where code = 'en'));
